insert into public.ticket_reopen_requests(id,organization_id,ticket_id,requested_by_user_id,requester_membership_id,resolved_at,ticket_revision,reason,created_at) select 'f9500000-0000-4000-8000-000000000010',organization_id,id,client_user_id,(select id from public.organization_members where user_id=client_user_id and status='active'),resolved_at,revision,'Fictional continuing problem',resolved_at+interval '1 hour' from public.tickets where id='f9400000-0000-4000-8000-000000000010';
insert into public.ticket_reopen_requests(id,organization_id,ticket_id,requested_by_user_id,requester_membership_id,resolved_at,ticket_revision,reason,created_at) select 'f9500000-0000-4000-8000-000000000012',organization_id,id,client_user_id,(select id from public.organization_members where user_id=client_user_id and status='active'),resolved_at,revision,'Fictional continuing problem',resolved_at+interval '1 hour' from public.tickets where id='f9400000-0000-4000-8000-000000000012';
insert into public.ticket_reopen_requests(id,organization_id,ticket_id,requested_by_user_id,requester_membership_id,resolved_at,ticket_revision,reason,created_at) select 'f9500000-0000-4000-8000-000000000015',organization_id,id,client_user_id,(select id from public.organization_members where user_id=client_user_id and status='active'),resolved_at,revision,'Fictional continuing problem',resolved_at+interval '1 hour' from public.tickets where id='f9400000-0000-4000-8000-000000000015';
insert into public.ticket_reopen_requests(id,organization_id,ticket_id,requested_by_user_id,requester_membership_id,resolved_at,ticket_revision,reason,created_at) select 'f9500000-0000-4000-8000-000000000020',organization_id,id,client_user_id,(select id from public.organization_members where user_id=client_user_id and status='active'),resolved_at,revision,'Fictional continuing problem',resolved_at+interval '1 hour' from public.tickets where id='f9400000-0000-4000-8000-000000000020';
create temp table resolution_context as select p.id,p.access_revision,(case p.app_role when 'client' then (select id::text from public.organization_members where user_id=p.id and organization_id='f9200000-0000-4000-8000-000000000001' and status='active') when 'admin' then (select revision::text from public.organization_admin_assignments where admin_user_id=p.id and organization_id='f9200000-0000-4000-8000-000000000001' and active) when 'staff' then (select revision::text from public.staff_organization_assignments where staff_user_id=p.id and organization_id='f9200000-0000-4000-8000-000000000001' and active) end) as scope from public.profiles p where id::text like 'f9100000-%'; grant select on resolution_context to authenticated;
